def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for x in row:
            counts[x] = counts.get(x, 0) + 1

    lines = []
    for r in range(h):
        if len(set(grid[r])) == 1:
            lines.append(("row", r, grid[r][0]))
    for c in range(w):
        vals = [grid[r][c] for r in range(h)]
        if len(set(vals)) == 1:
            lines.append(("col", c, vals[0]))

    # The boundary is the uniform line in the less frequent color;
    # other uniform lines can simply be background.
    axis, pos, wall_color = min(lines, key=lambda line: counts[line[2]])
    bg = max((color for color in counts if color != wall_color),
             key=lambda color: counts[color])

    obj = [(r, c) for r in range(h) for c in range(w)
           if grid[r][c] != bg and grid[r][c] != wall_color]
    out = [[bg] * w for _ in range(h)]

    if axis == "row":
        for c in range(w):
            out[pos][c] = wall_color
        toward = 1 if pos == 0 else -1
        near = min(r for r, c in obj) if toward == 1 else max(r for r, c in obj)
        shift = pos + toward - near
        moved = [(r + shift, c, grid[r][c]) for r, c in obj]
        stripe = (max(r for r, c, _ in moved) + 1 if toward == 1
                  else min(r for r, c, _ in moved) - 1)
        if 0 <= stripe < h:
            out[stripe] = [8] * w
        for r, c, color in moved:
            out[r][c] = color
    else:
        for r in range(h):
            out[r][pos] = wall_color
        toward = 1 if pos == 0 else -1
        near = min(c for r, c in obj) if toward == 1 else max(c for r, c in obj)
        shift = pos + toward - near
        moved = [(r, c + shift, grid[r][c]) for r, c in obj]
        stripe = (max(c for r, c, _ in moved) + 1 if toward == 1
                  else min(c for r, c, _ in moved) - 1)
        if 0 <= stripe < w:
            for r in range(h):
                out[r][stripe] = 8
        for r, c, color in moved:
            out[r][c] = color

    return out
